@dataclass
class FromUrlReport:
    """How one from_url call got its value."""

    url: str
    how: Literal["copied", "parsed", "not on page"] = "not on page"
    path: Literal["quick", "browser"] = "quick"
    steps: list[str] = field(default_factory=list)
    """Every browser tool call, in order, eg 'click: 1Y'."""
    parse_attempts: list[tuple[str, str]] = field(default_factory=list)
    """(parser code, its result or why it was refused), in order."""
    parse_code: str = ""
    """The parser that made the value (how == 'parsed')."""
    rows: int | None = None
    cost: float = 0.0
    """US dollars of the AI calls it made."""
    seconds: float = 0.0
    reason: str = ""
    """how == 'not on page': why."""
    what: str = ""
    """What was asked for, in words (from_url's third argument)."""
    clicks: list[str] = field(default_factory=list)
    """how == 'parsed': the visible labels clicked to load the data (what a script replays)."""
    response_contains: str = ""
    """how == 'parsed': the part of the data response's URL that identifies it."""
    repairs: str = ""
    """The saved script whose failure led to this call (ds.ai.scripts), "" when none."""

    @property
    def savable(self) -> bool:
        """Whether it can become a saved script: a browser run that ended in a parser."""
        return self.how == "parsed" and self.path == "browser" and bool(self.response_contains)

    def summary(self) -> str:
        """One line for the chat, eg 'from_url: browser, clicked
        1Y, parsed by an AI-written parser (3 tries)'.
        """
        where = "page text" if self.path == "quick" else "browser"
        clicks = [step.removeprefix("click: ") for step in self.steps if step.startswith("click: ")]
        parts = [f"from_url ({self.url}): {where}"]
        if clicks:
            parts.append("clicked " + ", ".join(clicks))
        if self.how == "parsed":
            parts.append(f"parsed by an AI-written parser ({len(self.parse_attempts)} tries)")
        elif self.how == "copied":
            parts.append("values copied by the AI (not checked)")
        elif self.reason:
            parts.append(f"not found: {self.reason}")
        if self.rows is not None:
            parts.append(f"{self.rows} rows")
        parts.append(f"{self.seconds:.0f} s, ${self.cost:.3f}")
        return ", ".join(parts)

    def detail(self) -> str:
        """Everything it did, as text: each browser step,
        each parser tried and what came of it.
        """
        lines = [self.summary()]
        if self.steps:
            lines += ["", "Browser steps:", *[f"  {n}. {step}" for n, step in enumerate(self.steps, 1)]]
        for n, (code, outcome) in enumerate(self.parse_attempts, 1):
            lines += ["", f"Parser try {n} -> {outcome[:300]}", code]
        if self.parse_code:
            lines += ["", "Parser that made the value:", self.parse_code]
        return "\n".join(lines)


_local = threading.local()


def reports() -> list[FromUrlReport]:
    """The reports of this thread's from_url calls since the last clear_reports()."""
    return list(getattr(_local, "reports", []))


def clear_reports() -> None:
    """Forget this thread's reports (before running code
    whose from_url calls should be reported).
    """
    _local.reports = []


def _keep(report: FromUrlReport) -> None:
    if not hasattr(_local, "reports"):
        _local.reports = []
    _local.reports.append(report)


